// oxlint-disable eslint/no-eval -- DIRECT `eval` is the subject under test, not an accident.
// It must be direct (not `(0, eval)`) so the payload inherits this module's CJS scope and can
// reach `require`, which is what the issue's PoC does and what makes the capability calls
// happen at all.
//
// Test-fixture dependency for issue #84 — attribution forgery via V8's `getEvalOrigin()`.
//
// INERT (AGENTS.md § 8): the "secret" is a placeholder this test's own runner puts in the
// environment and in `secret.txt`; nothing here is a real payload and nothing leaves the
// process. The point is to prove capwall attributes these calls to `forge-dep` (or
// `<unknown>`) and DENIES them, instead of charging them to the package `forge-dep` names.
//
// THE FORGERY. `//# sourceURL=` cannot on its own forge V8's `eval at …` origin form, because
// a `sourceURL` may not contain whitespace. But for a NESTED eval, V8 itself synthesizes the
// `eval at <fn> (…)` wrapper around the *outer* script's name — and the outer script's name is
// exactly what its own `sourceURL` set. Appending `:1:1` to the sourceURL (still no
// whitespace) makes the string V8 synthesizes indistinguishable from a genuine depth-1 origin:
//
//   inner  = "<payload>"
//   outer  = 'eval("<payload>")\n//# sourceURL=/proj/node_modules/forge-target/index.cjs:1:1'
//   eval(outer) ->  getEvalOrigin() === "eval at <anonymous> (…/forge-target/index.cjs:1:1)"
//
// The attacker never writes the `eval at ` prefix; V8 writes it for them.

const path = require("node:path");

const SECRET = "FORGE_FIXTURE_SECRET";
const SECRET_FILE = path.join(__dirname, "..", "..", "secret.txt");

/** Real, installed path of the one package the fixture policy grants. */
const TARGET_PATH = path.join(__dirname, "..", "forge-target", "index.cjs");
/** A real application source file — anything outside `node_modules` resolves to `<app>`. */
const APP_PATH = path.join(__dirname, "..", "..", "app.cjs");

/**
 * The two capability calls every vector performs, as a SOURCE STRING so the eval vectors
 * compile their own copy (a copy whose frames carry no file name, which is the whole point).
 *
 * `require` resolves through the enclosing CJS scope, so every vector must use DIRECT `eval`.
 */
const PAYLOAD = `(function () {
  const out = { env: undefined, fs: undefined };
  out.env = process.env[${JSON.stringify(SECRET)}];
  try {
    out.fs = require("node:fs").readFileSync(${JSON.stringify(SECRET_FILE)}, "utf8").trim();
  } catch (err) {
    out.fs = err && err.name === "CapabilityError" ? "DENIED:" + err.pkg : "THREW:" + err.message;
  }
  return out;
})()`;

/** Print the line protocol `app.cjs` and the test read. */
function report(out) {
  console.log(`env=${out.env === undefined ? "undefined" : out.env}`);
  console.log(`fs=${out.fs}`);
}

/**
 * The forgery primitive: run {@link PAYLOAD} two `eval` levels deep, with the OUTER level
 * claiming `sourceURL`. `origin` must contain no whitespace or V8 rejects the `sourceURL`
 * outright and reports the genuine origin instead (verified on Node 20 and 22).
 */
function nested(origin) {
  return eval(`eval(${JSON.stringify(PAYLOAD)})\n//# sourceURL=${origin}:1:1`);
}

const VECTORS = {
  /** Control: `forge-dep` calling honestly, from its own ordinary frames. */
  honest: () => eval(PAYLOAD),

  /** The issue's PoC: name the one package the policy grants. */
  "forge-pkg": () => nested(TARGET_PATH),

  /**
   * The issue's second PoC: name a file outside `node_modules`, which resolves to `<app>` —
   * the trust root, whose `process.env` reads the env shim exempts BEFORE the decision is
   * recorded, so a successful forgery here is also invisible to `observe` and `capwall diff`.
   */
  "forge-app": () => nested(APP_PATH),

  /**
   * Three levels instead of two. There is no nesting depth at which the innermost
   * parenthesised group stops being attacker-chosen, which is why no "count the `eval at `
   * tokens" / "take the outermost match" parse can separate a genuine origin from a forged
   * one — see the header of `attribution/index.ts`.
   */
  "forge-deep": () =>
    eval(
      `eval(${JSON.stringify(`eval(${JSON.stringify(PAYLOAD)})`)})\n//# sourceURL=${TARGET_PATH}:1:1`,
    ),

  /**
   * A UNICODE LOOK-ALIKE of the granted package name: `forge\u2011target` (non-breaking
   * hyphen) reads as `forge-target` but is a different string. Two things must hold: the
   * forgery must not work at all, and even if a path like this were trusted it must not
   * collapse onto the granted name through some normalization on the policy-lookup path.
   */
  "forge-unicode": () =>
    nested(path.join(__dirname, "..", "forge\u2011target", "index.cjs")),

  /**
   * A Windows-style absolute path. `packageForPath` splits on `path.sep`, so a backslash path
   * seen on POSIX has no `/node_modules/` segment at all and would resolve to `<app>` — the
   * trust root — rather than to nothing. Must be unreachable via the eval origin either way.
   */
  "forge-winpath": () => nested("C:\\proj\\node_modules\\forge-target\\index.cjs"),

  /** Mixed separators: absolute on POSIX, but the package segment spelled with a backslash. */
  "forge-mixedsep": () => nested(`${path.join(__dirname, "..")}\\forge-target/index.cjs`),

  /**
   * `vm.runInNewContext(code, { filename })` sets `getFileName()` on the resulting frames
   * directly — a forgery route that never touches `getEvalOrigin()`. It is gated: `vm` is a
   * capability and `forge-dep` has no grant, so the compile never happens. (WITH a `vm` grant
   * it does work, and that is the residual `docs/threat-model.md` already names.)
   */
  "forge-vm": () => {
    try {
      return require("node:vm").runInNewContext(PAYLOAD, { require, process, console }, {
        filename: TARGET_PATH,
      });
    } catch (err) {
      return {
        env: undefined,
        fs: err && err.name === "CapabilityError" ? "VMDENIED:" + err.pkg : "THREW:" + err.message,
      };
    }
  },

  /**
   * LEGITIMATE USE, pinned deliberately. A dependency compiling and immediately running its own
   * code (every template engine, `ajv`, …) keeps its own frame directly beneath the eval
   * frames, so it is still charged to `forge-dep` BY NAME. Treating eval frames as opaque does
   * not cost this case anything.
   */
  "dep-eval-sync": () => eval(PAYLOAD),

  /**
   * LEGITIMATE USE, pinned deliberately — and the case that DOES change. Detached through a
   * timer there is no real frame left on the stack, so this is `<unknown>` rather than
   * `forge-dep`. Fails closed; `<unknown>` is grantable if a real tree needs it.
   */
  "dep-eval-detached": () =>
    new Promise((resolve) => {
      globalThis.__forgeResolve = resolve;
      eval(`setTimeout(() => { globalThis.__forgeResolve(${PAYLOAD}); }, 0)`);
    }),
};

async function run(vector) {
  const fn = VECTORS[vector];
  if (fn === undefined) throw new Error(`unknown vector: ${vector}`);
  report(await fn());
}

module.exports = { run, VECTORS: Object.keys(VECTORS) };
